Here’s a sunrise effect for the cylindrical lamp:

```lsl
uniform float speed : 0.0 .. 5.0 = 0.6;
uniform float riseHeight : 0.0 .. 1.0 = 0.7;
uniform vec3 baseColor : color = 0.9, 0.3, 0.1;
uniform vec3 peakColor : color = 1.0, 0.8, 0.4;
uniform float spread : 0.0 .. 0.5 = 0.05;
state fixed risePhase;
state float riseOffset;
void update() {
  risePhase = fract(risePhase + fixed(dt * speed * 0.5));
  riseOffset = riseOffset + dt * speed * 0.3;
}
vec3 shade(Led led) {
  // Normalize vertical coordinate to [0,1] (bottom to top)
  fixed yNorm = fixed(led.pos.y) / fixed(0.30);
  // Compute sunrise wave: a smooth ramp that climbs from bottom to riseHeight
  fixed rise = clamp((yNorm - risePhase) * fixed(1.0 / riseHeight), fixed(0.0), fixed(1.0));
  // Add a soft roll‑off near the edges
  rise = rise * (fixed(1.0) - min(abs(yNorm - risePhase) * fixed(1.0 / spread), fixed(1.0)));
  // Blend between base and peak colors based on rise amount
  fixed t = rise;
  fixed r = mix(fixed(baseColor.r), fixed(peakColor.r), t);
  fixed g = mix(fixed(baseColor.g), fixed(peakColor.g), t);
  fixed b = mix(fixed(baseColor.b), fixed(peakColor.b), t);
  // Use the integer‑path hsv2rgb for speed (hue = t, full saturation & value)
  return hsv2rgb(fixed(t), fixed(1.0), fixed(1.0));
}
```

**Explanation**

* **Uniforms** expose live controls for sunrise speed, height, base/peak colors, and spread.
